create or replace function public.peran_saat_ini() returns public.peran_pengguna language sql stable security definer set search_path=public as $$ select peran from public.pengguna where id=auth.uid() and aktif=true $$;
alter table public.pengguna enable row level security;alter table public.berita enable row level security;alter table public.relawan enable row level security;alter table public.agenda enable row level security;alter table public.galeri enable row level security;
drop policy if exists pengguna_baca on public.pengguna;create policy pengguna_baca on public.pengguna for select to authenticated using(id=auth.uid() or public.peran_saat_ini() in('admin','superadmin'));
drop policy if exists berita_baca on public.berita;create policy berita_baca on public.berita for select to anon,authenticated using(status='terbit' or public.peran_saat_ini() in('editor','admin','superadmin'));
drop policy if exists berita_kelola on public.berita;create policy berita_kelola on public.berita for all to authenticated using(public.peran_saat_ini() in('editor','admin','superadmin')) with check(public.peran_saat_ini() in('editor','admin','superadmin'));
drop policy if exists relawan_kelola on public.relawan;create policy relawan_kelola on public.relawan for all to authenticated using(public.peran_saat_ini() in('admin','superadmin')) with check(public.peran_saat_ini() in('admin','superadmin'));
drop policy if exists agenda_baca on public.agenda;create policy agenda_baca on public.agenda for select to anon,authenticated using(true);
drop policy if exists agenda_kelola on public.agenda;create policy agenda_kelola on public.agenda for all to authenticated using(public.peran_saat_ini() in('editor','admin','superadmin')) with check(public.peran_saat_ini() in('editor','admin','superadmin'));
drop policy if exists galeri_baca on public.galeri;create policy galeri_baca on public.galeri for select to anon,authenticated using(tampil=true or public.peran_saat_ini() in('editor','admin','superadmin'));
drop policy if exists galeri_kelola on public.galeri;create policy galeri_kelola on public.galeri for all to authenticated using(public.peran_saat_ini() in('editor','admin','superadmin')) with check(public.peran_saat_ini() in('editor','admin','superadmin'));